// AwaitBuild returns nil at once unless Open found the shared database on Turso ahead of this
// build (a newer build migrated it). Then it is --jobs-only's maintenance page (jobs.AwaitBuild):
// it reads the database's schema again every 10 s (db.CheckShared) and returns nil once it is
// this build's, the web build's error once it is behind, or ctx's error when ctx ends first.
func (a *App) AwaitBuild(ctx context.Context) error {
	if a.web.SharedMaintenance == nil {
		return nil
	}
	return jobs.AwaitBuild(ctx, func(ctx context.Context) (db.SharedState, string, error) {
		return db.CheckShared(ctx, a.store, Tables, Migrations)
	}, nil, a.log)
}

// JobEnv is the Env an attempt of a job of kind k runs with, built as the router builds a
// request's (rt/web's newEnv without a request): web.Options.EnvFor's when it is set, with
// Session nil; else the store(s), the capabilities, the session check and the router's clock.
// Its Log is left to the worker, which writes the job's lines under its id.
func (a *App) JobEnv(ctx context.Context, k jobs.Kind) *eff.Env {
	if a.web.EnvFor != nil {
		env := a.web.EnvFor(ctx, nil)
		env.Session = nil
		return env
	}
	env := &eff.Env{Ctx: ctx, Store: a.web.Store, Caps: a.web.Caps, Now: a.now}
	if a.web.Stores != nil {
		env.Stores = a.web.Stores
	}
	env.CheckSession = a.web.SessionCheck
	return env
}

// Close closes the app's stores: the silos' (when it declares a `silo`), then the shared one.
func (a *App) Close() error {
	var errs []error
	if a.web.Stores != nil {
		errs = append(errs, a.web.Stores.Close())
	}
	errs = append(errs, a.store.Close())
	return errors.Join(errs...)
}

// Open opens the app. It checks that o.Secret is at least 16 bytes outside dev
